-- Status inicial ativo para cadastro operacional. Nenhuma conta de login criada.
begin;
create temporary table roster_import (like public.employees including defaults) on commit drop;
alter table roster_import enable row level security;
do $$ begin if exists (select 1 from public.employees e where not exists (select 1 from roster_import r where r.id=e.id)) then raise exception 'Cadastro existente: revisar antes de importar'; end if; end $$;
commit;
select count(*) as total, count(*) filter(where is_leader) as lideres, count(*) filter(where not is_leader) as colaboradores, count(*) filter(where not is_leader and leader_id is not null) as colaboradores_com_lider from public.employees;